    /** 0.0 to 1.0 for items in progress. */
    val progress: Float? = null,
    /** Video to resume for Continue Watching tiles. */
    val videoId: String? = null,
    /** The IMDb rating the addon gave, as written ("8.4"). */
    val rating: String? = null,
    /** The IMDb score to show, from the addon's own rating (`rating`). */
    val ratings: Ratings = Ratings(),
    /** The tile's place, 1 to 10, in a Top 10 row (`HomeRow::ranked`); none anywhere else. */
    val rank: Int? = null,
    /** The tile's first genre, under a Top 10 tile; none anywhere else. */
    val genre: String? = null,
)

@Serializable
data class TitleDetails(
    val id: String,
    val kind: String,
    val name: String,
    val description: String? = null,
    val poster: String? = null,
    /** RPDB's cover with the IMDb, Metacritic and Rotten Tomatoes band drawn in, as the title's tiles show it (`Tile::rated_cover`): for its IMDb id, or the one its addon gave an anime, with the RPDB key an installed, enabled addon was configured with. Null with no key or no IMDb id: show `poster` then, and `poster` too when this one fails to load. */
    val ratedPoster: String? = null,
    /** The poster at the size a phone's title page draws it, across the screen: metahub's large one (780x1170) when `poster` is metahub's small or medium, else `poster` as given. */
    val cover: String? = null,
    /** The cover is known to print the title (metahub's posters do): a phone draws no logo with it. False for another host's cover (an anime's Kitsu poster, an addon's own art), which keeps the logo or the name with it. */
    val coverTitled: Boolean = false,
    val background: String? = null,
    val logo: String? = null,
    val releaseInfo: String? = null,
    val runtime: String? = null,
    val genres: List<String> = emptyList(),
    /** From the meta's `Cast` links, in its order, each with TMDB's headshot and role once its credits land (asked with `scores`). */
    val cast: List<CastMember> = emptyList(),
    val directors: List<String> = emptyList(),
    /** From the meta's `Writers` links, as `cast` and `directors`. */
    val writers: List<String> = emptyList(),
    /** The IMDb rating the addon gave, as written ("8.4"). */
    val rating: String? = null,
    /** The IMDb score to show, as on tiles. */
    val ratings: Ratings = Ratings(),
    /** The title's IMDb page, for the IMDb score to link to; null for an id that is not IMDb's, and on a kids profile (no way out to the web). */
    val imdbUrl: String? = null,
    /** TMDB's and Trakt's numbers, asked once the page is visible (`titleVisible`). */
    val scores: TitleScores = TitleScores(Slot.None, Slot.None),
    val source: String,
    /** Trailers the metadata names (YouTube), first is the main one. */
    val trailers: List<Trailer> = emptyList(),
)

@Serializable
data class TitleHeader(
    val state: TitleState,
    val details: TitleDetails? = null,
    val inLibrary: Boolean,
    /** Add to Library can be offered: false on a kids profile, whose Library is the owner's list (`setInLibrary` is refused there). Hide the button when false. */
    val librarySettable: Boolean = true,
    /** Genres open Discover: false on a kids profile, which has no Discover (plans/m11-kids.md 14.1). Show the genres as plain text when false. */
    val genresLinked: Boolean = true,
    /** Subtitles for the video Play plays (core backlog C34): what the subtitles addons list for it, for the CC and SDH badges. Null until they answered, and with no subtitles addon. */
    val captions: Captions? = null,
    val seasons: List<Int> = emptyList(),
    val selectedSeason: Int? = null,
    /** Episode (or the movie itself) the primary button resumes or starts. None while the next episode is not out yet (see `next_airs`). */
    val playTarget: PlayTarget? = null,
    /** The day the next episode comes out ("YYYY-MM-DD", as `Episode::released`) when it is not out yet: there is no play target, and the page says "Next episode airs <date>". */
    val nextAirs: String? = null,
    /** A movie the user watched, or a title with episodes (a series, an anime) whose every aired regular episode is watched (specials left out, as Trakt counts a show complete; an episode with no season counts; core backlog C41). Toggled with `setWatched` on the title's id: with episodes that marks or unmarks every such one. */
    val watched: Boolean,
    /** The title is in Continue Watching on this profile: a video in progress, or a series finished up to an episode with a next one out (Next Up), as Home's row has it. With the header from the first render, so a control that depends on it (TV's Remove from Continue Watching) is drawn at once, never late. */
    val continuing: Boolean = false,
    /** A movie's download on this device (plans/offline-downloads.md 3.1). */
    val download: DownloadBadge? = null,
    /** The selected season's downloads, for its menu item. */
    val seasonDownload: GroupDownload? = null,
    /** Every regular season's, for "Download every season". */
    val seriesDownload: GroupDownload? = null,
    /** The meta could not be read and the page shows what the downloads kept (4.18): hide Versions and Trailer, say "Showing what's downloaded". */
    val offline: Boolean = false,
)

/** The title page's numbers beyond the addon's IMDb score, per source: TMDB's user score and Trakt's community score, each as a percentage ("87%", "92%"), shown only with at least 10 votes. */
@Serializable
data class TitleScores(
    val tmdb: Slot,
    val trakt: Slot,
)

@Serializable
data class TitleSnapshot(
    val header: TitleHeader,
    val episodes: List<Episode> = emptyList(),
    /** "More like this": empty until it lands, and for a kids profile. */
    val similar: List<Tile> = emptyList(),
)

